/** @description Adapts the greeting capability to a Next.js Route Handler. */

import { createGreeting } from '@workspace/greetings';
import { toDisplayName } from '@workspace/text';
import type { NextRequest } from 'next/server';

export function GET(request: NextRequest): Response {
	const name = request.nextUrl.searchParams.get('name') ?? '';
	const greeting = createGreeting({ name: toDisplayName(name) });

	if (!greeting.ok) {
		return Response.json({ error: greeting.error }, { status: 400 });
	}

	return Response.json({ message: greeting.value });
}

