/** @description Proves the public Next.js route contract across workspace boundaries. */

import { NextRequest } from 'next/server';
import { describe, expect, it } from 'vitest';

import { GET } from './route';

describe('GET /api/greet', () => {
	it('returns a normalized greeting', async () => {
		const response = GET(new NextRequest('http://localhost/api/greet?name=ada%20lovelace'));

		expect(response.status).toBe(200);
		await expect(response.json()).resolves.toEqual({ message: 'Hello, Ada Lovelace!' });
	});

	it('normalizes messy casing and whitespace through the private lib', async () => {
		const response = GET(
			new NextRequest('http://localhost/api/greet?name=%20%20gRACE%20%20%20hopper%20'),
		);

		expect(response.status).toBe(200);
		await expect(response.json()).resolves.toEqual({ message: 'Hello, Grace Hopper!' });
	});

	it('returns the typed empty-name failure', async () => {
		const response = GET(new NextRequest('http://localhost/api/greet'));

		expect(response.status).toBe(400);
		await expect(response.json()).resolves.toEqual({
			error: { code: 'EMPTY_NAME', message: 'A non-empty name is required.' },
		});
	});
});
